package org.apache.commons.jxpath.ri.compiler;

import java.io.*;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.HashSet;
import java.util.Iterator;
import org.apache.commons.jxpath.Expression;
import org.apache.commons.jxpath.Pointer;
import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.InfoSetUtil;
import org.apache.commons.jxpath.ri.axes.InitialContext;
import org.apache.commons.jxpath.ri.axes.SelfContext;
import org.apache.commons.jxpath.ri.compiler.CoreOperationCompare;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for CoreOperationCompare.equal method.
 * Since the method is protected, we use a test subclass to expose it.
 */
public class CoreOperationCompare_equal_TriageGen0Test {

    private TestableCoreOperationCompare compare;

    // Mocking Pointer interface/class as it's used in the logic
    // Assuming Pointer is an interface or class in the same package or accessible
    interface Pointer {
        Object getValue();
    }

    // Subclass to access protected method
    private static class TestableCoreOperationCompare extends CoreOperationCompare {
        public TestableCoreOperationCompare(Expression arg1, Expression arg2) {
            super(arg1, arg2);
        }

        @Override
        public boolean equal(Object l, Object r) {
            return super.equal(l, r);
        }
    }

    @Before
    public void setUp() {
        compare = new TestableCoreOperationCompare(mock(Expression.class), mock(Expression.class));
    }

    @Test
    public void testPointerEqualityDirect() {
        Pointer p1 = mock(Pointer.class);
        Pointer p2 = mock(Pointer.class);
        when(p1.equals(p2)).thenReturn(true);

        assertTrue("Direct Pointer equality should return true", compare.equal(p1, p2));
    }

    @Test
    public void testPointerEqualityDifferent() {
        Pointer p1 = mock(Pointer.class);
        Pointer p2 = mock(Pointer.class);
        when(p1.equals(p2)).thenReturn(false);

        // Fall through to getValue logic
        when(p1.getValue()).thenReturn(10);
        when(p2.getValue()).thenReturn(10);
        assertTrue("Should be equal after unwrapping pointers", compare.equal(p1, p2));
    }

    @Test
    public void testPointerUnwrapOneSide() {
        Pointer p1 = mock(Pointer.class);
        when(p1.getValue()).thenReturn("test");

        assertTrue("Unwrapping one side should work", compare.equal(p1, "test"));
        assertFalse("Unwrapping one side mismatch", compare.equal(p1, "other"));
    }

    @Test
    public void testNullAndIdentity() {
        assertTrue("Same object identity", compare.equal(new Object(), new Object() {
            @Override public boolean equals(Object obj) { return true; } // Just for safety
        }));
        // Note: The code uses l == r after unwrapping. 
        // If both are null, l == r is true.
        assertTrue("Both null should be true", compare.equal(null, null));
        assertFalse("One null should be false", compare.equal(null, "not null"));
    }

    @Test
    public void testBooleanLogic() {
        assertTrue("Boolean true == true", compare.equal(true, true));
        assertTrue("Boolean true == Boolean.TRUE", compare.equal(true, Boolean.TRUE));
        assertFalse("Boolean true != false", compare.equal(true, false));
        // Testing the branch where one side is Boolean
        assertFalse("Boolean vs String (not boolean)", compare.equal(true, "true"));
    }

    @Test
    public void testNumberLogic() {
        assertTrue("Integer vs Double", compare.equal(10, 10.0));
        assertTrue("Long vs Integer", compare.equal(10L, 10));
        assertFalse("Different numbers", compare.equal(10, 11));

        // Testing the branch where one side is Number
        assertTrue("Double vs Integer", compare.equal(5.5, 5.5));
    }

    @Test
    public void testStringLogic() {
        assertTrue("String equality", compare.equal("hello", "hello"));
        assertTrue("String vs Object with string value", compare.equal("hello", new String("hello")));
        assertFalse("String mismatch", compare.equal("hello", "world"));
    }

    @Test
    public void testGenericObjectEquality() {
        Object obj1 = new CustomObject("val");
        Object obj2 = new CustomObject("val");
        Object obj3 = new CustomObject("diff");

        assertTrue("Custom object equality", compare.equal(obj1, obj2));
        assertFalse("Custom object inequality", compare.equal(obj1, obj3));
        assertFalse("Null vs Object", compare.equal(null, obj1));
    }

    @Test
    public void testMixedPointerAndNonPointer() {
        Pointer p1 = mock(Pointer.class);
        when(p1.getValue()).thenReturn(100);

        assertTrue("Pointer to Number vs Number", compare.equal(p1, 100));
        assertTrue("Pointer to String vs String", compare.equal(p1, "100".equals("100") ? "100" : null));
    }

    // Helper class for testing generic equality
    private static class CustomObject {
        private final String val;
        CustomObject(String val) { this.val = val; }
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            CustomObject that = (CustomObject) o;
            return val.equals(that.val);
        }
        @Override
        public int hashCode() { return val.hashCode(); }
    }
}
